VALUES
(7001, 6001, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Chanclas Havaianas Top Brasil Unisex Originales', 'chanclas-havaianas-top-brasil-unisex-originales-7001', 'Chanclas Havaianas clásicas elaboradas en 100% caucho de alta resistencia. Suela antideslizante y tiras confortables para playa y uso diario. Garantía oficial de fábrica.', 65000, 55250, 8, 'SEED-PROD-7001', 'Havaianas', 'NUEVO', TRUE, FALSE, 4.7, 18, 1, NOW() - INTERVAL '19 days', NOW() - INTERVAL '19 days'),
(7002, 6002, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Sandalias Havaianas Slim Elegance Mujer', 'sandalias-havaianas-slim-elegance-mujer-7002', 'Sandalias brasileñas con tiras finas elegantes y acabado metalizado brillante. Máximo confort y ligereza para climas cálidos y outfits frescos en Cartagena.', 75000, NULL, 46, 'SEED-PROD-7002', 'Havaianas', 'NUEVO', TRUE, FALSE, 4.8, 12, 3, NOW() - INTERVAL '27 days', NOW() - INTERVAL '27 days'),
(7003, 6003, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%audio%' OR LOWER(nombre) LIKE '%audífono%' OR LOWER(nombre) LIKE '%audifono%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%tecnolog%' LIMIT 1), 1), 'Auriculares Inalámbricos Bluetooth 5.3 Sony WH-CH520', 'auriculares-inal-mbricos-bluetooth-5-3-sony-wh-ch520-7003', 'Audífonos inalámbricos de diadema con hasta 50 horas de autonomía y carga rápida. Conexión multipunto y tecnología DSEE para restauración de audio comprimido.', 285000, NULL, 29, 'SEED-PROD-7003', 'Sony', 'NUEVO', TRUE, FALSE, 4.6, 5, 2, NOW() - INTERVAL '20 days', NOW() - INTERVAL '20 days'),
(7004, 6004, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%audio%' OR LOWER(nombre) LIKE '%audífono%' OR LOWER(nombre) LIKE '%audifono%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%tecnolog%' LIMIT 1), 1), 'Audífonos Sony WH-1000XM5 Cancelación de Ruido Premium', 'aud-fonos-sony-wh-1000xm5-cancelaci-n-de-ruido-premium-7004', 'Cancelación de ruido líder en la industria con dos procesadores y ocho micrófonos. Audio de alta resolución LDAC y llamadas ultra nítidas con inteligencia artificial.', 1450000, 1160000, 42, 'SEED-PROD-7004', 'Sony', 'NUEVO', TRUE, FALSE, 4.6, 20, 3, NOW() - INTERVAL '33 days', NOW() - INTERVAL '33 days'),
(7005, 6005, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%videojuego%' OR LOWER(nombre) LIKE '%juguete%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%tecnolog%' LIMIT 1), 1), 'Consola Nintendo Switch OLED 64GB Edición Blanca', 'consola-nintendo-switch-oled-64gb-edici-n-blanca-7005', 'Pantalla OLED vibrante de 7 pulgadas con colores intensos y alto contraste. Soporte ajustable ancho, puerto LAN integrado en la base y 64 GB de almacenamiento interno.', 1690000, NULL, 43, 'SEED-PROD-7005', 'Nintendo', 'NUEVO', TRUE, FALSE, 4.6, 10, 1, NOW() - INTERVAL '4 days', NOW() - INTERVAL '4 days'),
(7006, 6006, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%smartphone%' OR LOWER(nombre) LIKE '%celular%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%tecnolog%' LIMIT 1), 1), 'Apple iPhone 15 128GB Chip A16 Bionic USB-C', 'apple-iphone-15-128gb-chip-a16-bionic-usb-c-7006', 'Dynamic Island, cámara principal de 48 MP con teleobjetivo 2x y diseño duradero de vidrio tintado en masa y aluminio aeroespacial. Puerto universal USB-C.', 3890000, NULL, 16, 'SEED-PROD-7006', 'Apple', 'NUEVO', TRUE, FALSE, 4.8, 20, 0, NOW() - INTERVAL '3 days', NOW() - INTERVAL '3 days'),
(7007, 6007, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%computador%' OR LOWER(nombre) LIKE '%laptop%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%tecnolog%' LIMIT 1), 1), 'MacBook Air 13 Pulgadas Chip Apple M3 256GB SSD', 'macbook-air-13-pulgadas-chip-apple-m3-256gb-ssd-7007', 'Superligero y con solo 1.13 cm de grosor. Pantalla Liquid Retina de 13.6 pulgadas, batería de hasta 18 horas y cámara FaceTime HD de 1080p.', 5350000, 4280000, 30, 'SEED-PROD-7007', 'Apple', 'NUEVO', TRUE, FALSE, 4.9, 12, 2, NOW() - INTERVAL '39 days', NOW() - INTERVAL '39 days'),
(7008, 6008, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%gimnasio%' OR LOWER(nombre) LIKE '%ciclismo%' OR LOWER(nombre) LIKE '%deporte%' OR LOWER(nombre) LIKE '%fitness%' ORDER BY id DESC LIMIT 1), 4), 'Apple Watch Series 9 GPS 45mm Caja de Aluminio', 'apple-watch-series-9-gps-45mm-caja-de-aluminio-7008', 'Nuevo chip S9 SiP con gesto de doble toque sin tocar la pantalla. Pantalla dos veces más brillante, monitoreo avanzado de salud cardíaca y oxígeno en sangre.', 2150000, NULL, 25, 'SEED-PROD-7008', 'Apple', 'NUEVO', TRUE, FALSE, 4.7, 16, 2, NOW() - INTERVAL '38 days', NOW() - INTERVAL '38 days'),
(7009, 6009, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%smartphone%' OR LOWER(nombre) LIKE '%celular%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%tecnolog%' LIMIT 1), 1), 'Samsung Galaxy S24 Ultra 256GB Titanium Gray', 'samsung-galaxy-s24-ultra-256gb-titanium-gray-7009', 'Marco de titanio de grado aeroespacial, Galaxy AI integrada para traducción en vivo, zoom óptico 5x de 50 MP y lápiz S Pen integrado de ultra baja latencia.', 4990000, NULL, 19, 'SEED-PROD-7009', 'Samsung', 'NUEVO', TRUE, FALSE, 4.9, 10, 1, NOW() - INTERVAL '22 days', NOW() - INTERVAL '22 days'),
(7010, 6010, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Tenis Urbanos Nike Air Force 1 07 Low Cuero Blanco', 'tenis-urbanos-nike-air-force-1-07-low-cuero-blanco-7010', 'El ícono clásico del baloncesto llevado al streetwear urbano. Cuero prémium fácil de limpiar, costuras reforzadas y amortiguación Nike Air para confort todo el día.', 520000, 416000, 32, 'SEED-PROD-7010', 'Nike', 'NUEVO', TRUE, FALSE, 4.7, 3, 0, NOW() - INTERVAL '37 days', NOW() - INTERVAL '37 days'),
(7011, 6011, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Zapatillas de Running Adidas Ultraboost Light', 'zapatillas-de-running-adidas-ultraboost-light-7011', 'Nuestra tecnología Boost más ligera hasta la fecha para un retorno de energía sin precedentes. Exterior tejido Primeknit+ que abraza el pie con soporte focalizado.', 680000, NULL, 25, 'SEED-PROD-7011', 'Adidas', 'NUEVO', TRUE, FALSE, 4.8, 16, 0, NOW() - INTERVAL '7 days', NOW() - INTERVAL '7 days'),
(7012, 6012, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%cocina%' OR LOWER(nombre) LIKE '%menaje%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%hogar%' LIMIT 1), 3), 'Freidora de Aire Digital Oster Bioceramic 4 Litros', 'freidora-de-aire-digital-oster-bioceramic-4-litros-7012', 'Cocina hasta un 99.5% menos aceite con revestimiento cerámico Bioceramic antiadherente y libre de PTFE. 7 programas digitales preestablecidos de cocción.', 320000, NULL, 27, 'SEED-PROD-7012', 'Oster', 'NUEVO', TRUE, FALSE, 4.8, 10, 1, NOW() - INTERVAL '43 days', NOW() - INTERVAL '43 days'),
(7013, 6013, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%cocina%' OR LOWER(nombre) LIKE '%menaje%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%hogar%' LIMIT 1), 3), 'Licuadora Reversible Oster Profesional Motor 1000W', 'licuadora-reversible-oster-profesional-motor-1000w-7013', 'Cuchilla con tecnología de motor reversible que gira hacia adelante y hacia atrás. Vaso de vidrio Boroclass resistente a choques térmicos e ingredientes hirviendo.', 380000, 323000, 11, 'SEED-PROD-7013', 'Oster', 'NUEVO', TRUE, FALSE, 4.6, 10, 0, NOW() - INTERVAL '14 days', NOW() - INTERVAL '14 days'),
(7014, 6014, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%cuidado de la piel%' OR LOWER(nombre) LIKE '%piel%' OR LOWER(nombre) LIKE '%belleza%' OR LOWER(nombre) LIKE '%cuidado%' ORDER BY id DESC LIMIT 1), 5), 'Essence Mascara Lash Princess', 'essence-mascara-lash-princess-7014', 'The Essence Mascara Lash Princess is a popular mascara known for its volumizing and lengthening effects. Achieve dramatic lashes with this long-lasting and cruelty-free formula. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 45000, NULL, 15, 'SEED-PROD-7014', 'Essence', 'NUEVO', TRUE, FALSE, 4.6, 18, 0, NOW() - INTERVAL '20 days', NOW() - INTERVAL '20 days'),
(7015, 6015, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%cuidado de la piel%' OR LOWER(nombre) LIKE '%piel%' OR LOWER(nombre) LIKE '%belleza%' OR LOWER(nombre) LIKE '%cuidado%' ORDER BY id DESC LIMIT 1), 5), 'Eyeshadow Palette with Mirror - Glamour Beauty', 'eyeshadow-palette-with-mirror-glamour-beauty-7015', 'The Eyeshadow Palette with Mirror offers a versatile range of eyeshadow shades for creating stunning eye looks. With a built-in mirror, it''s convenient for on-the-go makeup application. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 79000, NULL, 20, 'SEED-PROD-7015', 'Glamour Beauty', 'NUEVO', TRUE, FALSE, 4.7, 14, 1, NOW() - INTERVAL '25 days', NOW() - INTERVAL '25 days'),
(7016, 6016, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%cuidado de la piel%' OR LOWER(nombre) LIKE '%piel%' OR LOWER(nombre) LIKE '%belleza%' OR LOWER(nombre) LIKE '%cuidado%' ORDER BY id DESC LIMIT 1), 5), 'Powder Canister - Velvet Touch', 'powder-canister-velvet-touch-7016', 'The Powder Canister is a finely milled setting powder designed to set makeup and control shine. With a lightweight and translucent formula, it provides a smooth and matte finish. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 59000, 44250, 23, 'SEED-PROD-7016', 'Velvet Touch', 'NUEVO', TRUE, FALSE, 4.7, 9, 2, NOW() - INTERVAL '22 days', NOW() - INTERVAL '22 days'),
(7017, 6017, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%cuidado de la piel%' OR LOWER(nombre) LIKE '%piel%' OR LOWER(nombre) LIKE '%belleza%' OR LOWER(nombre) LIKE '%cuidado%' ORDER BY id DESC LIMIT 1), 5), 'Red Lipstick - Chic Cosmetics', 'red-lipstick-chic-cosmetics-7017', 'The Red Lipstick is a classic and bold choice for adding a pop of color to your lips. With a creamy and pigmented formula, it provides a vibrant and long-lasting finish. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 51000, NULL, 34, 'SEED-PROD-7017', 'Chic Cosmetics', 'NUEVO', TRUE, FALSE, 4.6, 3, 0, NOW() - INTERVAL '38 days', NOW() - INTERVAL '38 days'),
(7018, 6018, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%cuidado de la piel%' OR LOWER(nombre) LIKE '%piel%' OR LOWER(nombre) LIKE '%belleza%' OR LOWER(nombre) LIKE '%cuidado%' ORDER BY id DESC LIMIT 1), 5), 'Red Nail Polish - Nail Couture', 'red-nail-polish-nail-couture-7018', 'The Red Nail Polish offers a rich and glossy red hue for vibrant and polished nails. With a quick-drying formula, it provides a salon-quality finish at home. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 45000, NULL, 41, 'SEED-PROD-7018', 'Nail Couture', 'NUEVO', TRUE, FALSE, 4.7, 4, 2, NOW() - INTERVAL '38 days', NOW() - INTERVAL '38 days'),
(7019, 6019, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%cuidado de la piel%' OR LOWER(nombre) LIKE '%piel%' OR LOWER(nombre) LIKE '%belleza%' OR LOWER(nombre) LIKE '%cuidado%' ORDER BY id DESC LIMIT 1), 5), 'Calvin Klein CK One', 'calvin-klein-ck-one-7019', 'CK One by Calvin Klein is a classic unisex fragrance, known for its fresh and clean scent. It''s a versatile fragrance suitable for everyday wear. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 197000, 147750, 24, 'SEED-PROD-7019', 'Calvin Klein', 'NUEVO', TRUE, FALSE, 4.6, 7, 1, NOW() - INTERVAL '35 days', NOW() - INTERVAL '35 days'),
