(7537, 6017, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%smartphone%' OR LOWER(nombre) LIKE '%celular%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%tecnolog%' LIMIT 1), 1), 'Selfie Lamp with iPhone - GadgetMaster', 'selfie-lamp-with-iphone-gadgetmaster-7537', 'The Selfie Lamp with iPhone is a portable and adjustable LED light designed to enhance your selfies and video calls. Attach it to your iPhone for well-lit photos. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 59000, NULL, 37, 'SEED-PROD-7537', 'GadgetMaster', 'NUEVO', TRUE, FALSE, 4.8, 16, 3, NOW() - INTERVAL '39 days', NOW() - INTERVAL '39 days'),
(7538, 6018, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%tecnolog%' LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 1), 'Selfie Stick Monopod - SnapTech', 'selfie-stick-monopod-snaptech-7538', 'The Selfie Stick Monopod is a extendable and foldable device for capturing the perfect selfie or group photo. Compatible with smartphones and cameras. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 51000, 40800, 35, 'SEED-PROD-7538', 'SnapTech', 'NUEVO', TRUE, FALSE, 4.8, 7, 3, NOW() - INTERVAL '41 days', NOW() - INTERVAL '41 days'),
(7539, 6019, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%tecnolog%' LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 1), 'TV Studio Camera Pedestal - ProVision', 'tv-studio-camera-pedestal-provision-7539', 'The TV Studio Camera Pedestal is a professional-grade camera support system for smooth and precise camera movements in a studio setting. Ideal for broadcast and production. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 1975000, NULL, 35, 'SEED-PROD-7539', 'ProVision', 'NUEVO', TRUE, FALSE, 4.9, 11, 2, NOW() - INTERVAL '35 days', NOW() - INTERVAL '35 days'),
(7540, 6020, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%herramientas eléctricas%' OR LOWER(nombre) LIKE '%herramienta%' OR LOWER(nombre) LIKE '%automotriz%' ORDER BY id DESC LIMIT 1), 6), 'Generic Motorcycle - Generic Motors', 'generic-motorcycle-generic-motors-7540', 'The Generic Motorcycle is a versatile and reliable bike suitable for various riding preferences. With a balanced design, it provides a comfortable and efficient riding experience. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 15800000, NULL, 42, 'SEED-PROD-7540', 'Generic Motors', 'NUEVO', TRUE, FALSE, 4.8, 10, 3, NOW() - INTERVAL '12 days', NOW() - INTERVAL '12 days');
